class Solution {
public:
    vector<int> smallestMissingValueSubtree(vector<int>& parents, vector<int>& nums) {
        int n = parents.size();
        vector<int> ans(n, 1);
        int node1 = -1;
        for (int i = 0; i < n; ++i) {
            if (nums[i] == 1) {
                node1 = i;
                break;
            }
        }
        if (node1 == -1) return ans;

        vector<vector<int>> children(n);
        for (int i = 1; i < n; ++i) {
            children[parents[i]].push_back(i);
        }

        vector<bool> visited(n, false);
        unordered_set<int> seen;

        auto dfs = [&](auto& self, int u) -> void {
            if (visited[u]) return;
            visited[u] = true;
            seen.insert(nums[u]);
            for (int v : children[u]) {
                self(self, v);
            }
        };

        int curr = node1;
        int mex = 1;
        while (curr != -1) {
            dfs(dfs, curr);
            while (seen.count(mex)) mex++;
            ans[curr] = mex;
            curr = parents[curr];
        }
        return ans;
    }
};

class Solution {
    private void dfs(int u, List<List<Integer>> children, int[] nums, boolean[] visited, Set<Integer> seen) {
        if (visited[u]) return;
        visited[u] = true;
        seen.add(nums[u]);
        for (int v : children.get(u)) {
            dfs(v, children, nums, visited, seen);
        }
    }
    public int[] smallestMissingValueSubtree(int[] parents, int[] nums) {
        int n = parents.length;
        int[] ans = new int[n];
        Arrays.fill(ans, 1);
        int node1 = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] == 1) {
                node1 = i;
                break;
            }
        }
        if (node1 == -1) return ans;

        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i < n; i++) children.add(new ArrayList<>());
        for (int i = 1; i < n; i++) children.get(parents[i]).add(i);

        boolean[] visited = new boolean[n];
        Set<Integer> seen = new HashSet<>();
        int curr = node1;
        int mex = 1;
        while (curr != -1) {
            dfs(curr, children, nums, visited, seen);
            while (seen.contains(mex)) mex++;
            ans[curr] = mex;
            curr = parents[curr];
        }
        return ans;
    }
}

var smallestMissingValueSubtree = function(parents, nums) {
  const n = parents.length;
  const ans = new Array(n).fill(1);
  const node1 = nums.indexOf(1);
  if (node1 === -1) return ans;

  const children = Array.from({ length: n }, () => []);
  for (let i = 1; i < n; i++) {
    children[parents[i]].push(i);
  }

  const visited = new Array(n).fill(false);
  const seen = new Set();

  function dfs(u) {
    if (visited[u]) return;
    visited[u] = true;
    seen.add(nums[u]);
    for (const v of children[u]) dfs(v);
  }

  let curr = node1;
  let mex = 1;
  while (curr !== -1) {
    dfs(curr);
    while (seen.has(mex)) mex++;
    ans[curr] = mex;
    curr = parents[curr];
  }
  return ans;
};
